(r, big) => {
  const n = big ? 100 : r.int(1, 5), A = r.pick(["ab", "abc"]);
  const a = r.str(n, A), t = a.split("");
  const k = r.int(0, 3);
  if (k === 1) { const i = r.int(0, n - 1), j = r.int(0, n - 1); [t[i], t[j]] = [t[j], t[i]]; }
  else if (k === 2) t[r.int(0, n - 1)] = r.str(1, A);
  else if (k === 3) return [a, r.str(n, A)];
  return [a, t.join("")];
}

