function atMostOneSwap(a: string, b: string): boolean {
  if (a === b) return true;
  const s = a.split("");
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j < s.length; j++) {
      [s[i], s[j]] = [s[j], s[i]];
      if (s.join("") === b) return true;
      [s[i], s[j]] = [s[j], s[i]];
    }
  }
  return false;
}

