function atMostOneSwap(a: string, b: string): boolean {
  const diff: number[] = [];
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) {
      diff.push(i);
      if (diff.length > 2) return false;
    }
  }
  if (diff.length === 0) return true;
  if (diff.length !== 2) return false;
  const [i, j] = diff;
  return a[i] === b[j] && a[j] === b[i];
}

